require("default.hypr.bindings.media")
o.bind("SUPER + ALT + SPACE", "Apps menu", "omarchy-menu toggle")
o.bind("SUPER + comma", "Dismiss last notification", "omarchy-shell notifications dismissOne")
-- o.bind("SUPER + RETURN", "Terminal", { omarchy = "terminal" })

-- custom binds
hl.bind("ALT + space", hl.dsp.exec_cmd("wlr-which-key"), { description = "Whichkey" })
hl.bind("SUPER + P", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | wl-copy"), { description = "Capture region to clipboard" })
hl.bind("SUPER + Q", hl.dsp.window.close(), { description = "Close active window" })
hl.bind("SUPER + return", hl.dsp.exec_cmd("uwsm-app -- xdg-terminal-exec --dir=\"$(omarchy-cmd-terminal-cwd)\""), { description = "Terminal" })
hl.bind("SUPER + space", hl.dsp.exec_cmd("vicinae toggle"), { description = "Vicinae" })
hl.bind("SUPER + ALT + C", hl.dsp.exec_cmd("vicinae vicinae://launch/clipboard/history"), { description = "Clipboard" })
hl.bind("SUPER + CTRL + Q", hl.dsp.exec_cmd("loginctl lock-session"), { description = "Lock screen" })
hl.bind("SUPER + SHIFT + C", hl.dsp.exec_cmd("omarchy-launch-browser --profile-directory=\"Profile 2\""), { description = "Browser - Cleo" })
hl.bind("SUPER + SHIFT + B", hl.dsp.exec_cmd("omarchy-launch-browser --profile-directory=Default"), { description = "Browser" })
hl.bind("SUPER + SHIFT + E", hl.dsp.exec_cmd("omarchy-launch-or-focus emacs \"uwsm app -- emacs\""), { description = "Emacs" })
hl.bind("SUPER + SHIFT + P", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | tesseract stdin stdout -l eng | wl-copy"), { description = "OCR" })

hl.bind("SUPER + ALT + T", hl.dsp.exec_cmd("~/.config/hypr/custom/scripts/tile-all-windows.sh"), { description = "Tile all" })
hl.bind("SUPER + ALT + V", hl.dsp.exec_cmd("~/.config/hypr/custom/scripts/float-all-windows.sh"), { description = "Float all" })

-- make sure we always open webapps with the right profile
