hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("omarchy-launch-webapp \"https://app.slack.com/client/T0D8K6092\" --profile-directory=\"Profile 2\""), { description = "Slack" })
hl.bind("SUPER + SHIFT + W", hl.dsp.exec_cmd("omarchy-launch-webapp \"https://web.whatsapp.com/\" --profile-directory=Default"), { description = "WhatsApp" })

-- set class names for tuis
hl.bind("SUPER + SHIFT + D", hl.dsp.exec_cmd("$TERMINAL --class=docker -e lazydocker"), { description = "Docker" })

