-- hyprswitch application switcher
hl.bind("SUPER + tab", hl.dsp.exec_cmd("hyprswitch gui --do-initial-execute --sort-recent"))
hl.bind("SUPER + tab", hl.dsp.submap("switch"))
-- release
hl.bind("SUPER + SUPER_L", hl.dsp.exec_cmd("hyprswitch close"), { release = true, transparent = true })
hl.bind("SUPER + SUPER_L", hl.dsp.submap("reset"), { release = true, transparent = true })
hl.bind("SUPER + SUPER_R", hl.dsp.exec_cmd("hyprswitch close"), { release = true, transparent = true })
hl.bind("SUPER + SUPER_R", hl.dsp.submap("reset"), { release = true, transparent = true })

hl.define_submap("switch", function()
    -- allow repeated window switching in submap (same keys as repeating while starting)
    hl.bind("SUPER + tab", hl.dsp.exec_cmd("hyprswitch gui -m --sort-recent"))
    hl.bind("SUPER + right", hl.dsp.exec_cmd("hyprswitch gui -m --sort-recent"))
    hl.bind("SUPER + SHIFT + tab", hl.dsp.exec_cmd("hyprswitch gui -r --sort-recent"))
    hl.bind("SUPER + left", hl.dsp.exec_cmd("hyprswitch gui -r --sort-recent"))

    -- close without going to window
    hl.bind("escape", hl.dsp.exec_cmd("hyprswitch close --kill"))
    hl.bind("escape", hl.dsp.submap("reset"))
end)

hl.bind("SUPER + grave", hl.dsp.exec_cmd("hyprswitch simple -s"))
hl.bind("SUPER + SHIFT + grave", hl.dsp.exec_cmd("hyprswitch simple -s -r"))

hl.bind("SUPER + ALT + CTRL + H", hl.dsp.window.move({ monitor = "l" }))
hl.bind("SUPER + ALT + CTRL + left", hl.dsp.window.move({ monitor = "l" }))
hl.bind("SUPER + ALT + CTRL + L", hl.dsp.window.move({ monitor = "r" }))
hl.bind("SUPER + ALT + CTRL + right", hl.dsp.window.move({ monitor = "r" }))

hl.bind("SUPER + ALT + L", hl.dsp.exec_cmd("~/.config/hypr/custom/scripts/switch-keyboard-profile.sh \"laptop\""), { description = "Set keyboard to Laptop" })
hl.bind("SUPER + ALT + M", hl.dsp.exec_cmd("~/.config/hypr/custom/scripts/switch-keyboard-profile.sh \"split\""), { description = "Set keyboard to Split" })
